"use client";

import { Select as SelectPrimitive } from "@base-ui/react/select";
import {
  Check as CheckIcon,
  ChevronDown as ChevronDownIcon,
  ChevronUp as ChevronUpIcon,
} from "lucide-react";
import type * as React from "react";
import { cn } from "@/lib/utils";

function mergeClassName<State>(
  base: string,
  className: string | ((state: State) => string | undefined) | undefined
): string | ((state: State) => string) {
  return typeof className === "function"
    ? (state) => cn(base, className(state))
    : cn(base, className);
}
const POPUP_ITEM_HEIGHT = "h-9 [[data-size=compact]_&]:h-8";

// =============================================================================
// Select (Root)
// =============================================================================
const Select = SelectPrimitive.Root;

// =============================================================================
// SelectGroup
// =============================================================================
export interface SelectGroupProps extends SelectPrimitive.Group.Props {}

function SelectGroup({ className, ...props }: SelectGroupProps) {
  return (
    <SelectPrimitive.Group
      className={mergeClassName("scroll-my-1 px-1", className)}
      data-slot="select-group"
      {...props}
    />
  );
}

// =============================================================================
// SelectValue
// =============================================================================
export interface SelectValueProps extends SelectPrimitive.Value.Props {}

function SelectValue({ className, ...props }: SelectValueProps) {
  return (
    <SelectPrimitive.Value
      className={mergeClassName(
        // Block, not flex: an ellipsis is drawn by the box whose own line
        // overflows, and a flex container's text sits in an anonymous item it
        // cannot ellipsize. Icons stay inline beside the label instead.
        "block min-w-0 flex-1 truncate text-left [&>svg]:me-1.5 [&>svg]:inline-block [&>svg]:align-[-0.2em]",
        className
      )}
      data-slot="select-value"
      {...props}
    />
  );
}

// =============================================================================
// SelectTrigger
// =============================================================================
export interface SelectTriggerProps extends SelectPrimitive.Trigger.Props {
  /**
   * Size variant of the trigger
   * @default "default"
   */
  size?: "sm" | "default";
}

function SelectTrigger({
  className,
  size = "default",
  children,
  ...props
}: SelectTriggerProps) {
  return (
    <SelectPrimitive.Trigger
      className={mergeClassName(
        "group flex w-fit min-w-0 max-w-full select-none items-center justify-between gap-1.5 whitespace-nowrap rounded-md border border-input bg-input-bg py-2 pr-2 pl-3 text-sm shadow-xs outline-none transition-[color] focus:border-ring focus:ring-1 focus:ring-ring focus:ring-inset disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive data-[size=default]:h-(--ks-control-md,2.5rem) data-[size=sm]:h-(--ks-control-sm,2rem) data-[popup-open]:border-ring data-placeholder:text-muted-foreground/70 data-[popup-open]:ring-1 data-[popup-open]:ring-ring data-[popup-open]:ring-inset dark:aria-invalid:ring-destructive [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
        className
      )}
      data-size={size}
      data-slot="select-trigger"
      {...props}
    >
      {children}
      <SelectPrimitive.Icon
        render={
          <ChevronDownIcon className="pointer-events-none size-4 shrink-0 text-muted-foreground transition-transform duration-(--duration-fast,125ms) ease-(--ease-ks-out,cubic-bezier(0.23,1,0.32,1)) group-data-[popup-open]:rotate-180" />
        }
      />
    </SelectPrimitive.Trigger>
  );
}

// =============================================================================
// SelectContent
// =============================================================================
export interface SelectContentProps extends SelectPrimitive.Popup.Props {
  /**
   * Alignment of the content
   * @default "center"
   */
  align?: "start" | "center" | "end";
  /**
   * Whether to align the selected item with the trigger
   * @default false
   */
  alignItemWithTrigger?: boolean;
  /**
   * Offset along the alignment axis
   * @default 0
   */
  alignOffset?: number;
  /**
   * Side of the trigger to position the popup
   * @default "bottom"
   */
  side?: "top" | "bottom" | "left" | "right" | "inline-start" | "inline-end";
  /**
   * Offset from the trigger
   * @default 4
   */
  sideOffset?: number;
  /**
   * Size of the menu items
   * @default "default"
   */
  size?: "default" | "compact";
}

function SelectContent({
  className,
  children,
  side = "bottom",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  alignItemWithTrigger = false,
  size = "default",
  ...props
}: SelectContentProps) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        align={align}
        alignItemWithTrigger={alignItemWithTrigger}
        alignOffset={alignOffset}
        className="z-(--z-popover,60)"
        side={side}
        sideOffset={sideOffset}
      >
        <SelectPrimitive.Popup
          className={mergeClassName(
            "relative isolate max-h-(--available-height) w-(--anchor-width) min-w-36 max-w-(--available-width) origin-(--transform-origin) overflow-hidden rounded-lg bg-popover text-popover-foreground shadow-lg ring-1 ring-popup-ring",
            className
          )}
          data-align-trigger={alignItemWithTrigger}
          data-size={size}
          data-slot="select-content"
          {...props}
        >
          <SelectPrimitive.List className="max-h-(--available-height) overflow-y-auto py-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
            <SelectScrollUpButton />
            {children}
            <SelectScrollDownButton />
          </SelectPrimitive.List>
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  );
}

// =============================================================================
// SelectLabel
// =============================================================================
export interface SelectLabelProps extends SelectPrimitive.GroupLabel.Props {}

function SelectLabel({ className, ...props }: SelectLabelProps) {
  return (
    <SelectPrimitive.GroupLabel
      className={mergeClassName(
        "px-1.5 py-1 text-muted-foreground text-xs",
        className
      )}
      data-slot="select-label"
      {...props}
    />
  );
}

// =============================================================================
// SelectItem
// =============================================================================
export interface SelectItemProps extends SelectPrimitive.Item.Props {
  children: React.ReactNode;
  /**
   * Custom indicator to show when item is selected.
   * Set to `null` to hide the indicator.
   * @default <CheckIcon />
   */
  indicator?: React.ReactNode;
}

function SelectItem({
  className,
  children,
  indicator,
  ...props
}: SelectItemProps) {
  const showDefaultIndicator = indicator === undefined;
  const showCustomIndicator = indicator !== undefined && indicator !== null;

  return (
    <SelectPrimitive.Item
      className={mergeClassName(
        cn(
          `relative flex focus:bg-accent focus:text-accent-foreground not-data-[variant=destructive]:focus:*:text-accent-foreground ${POPUP_ITEM_HEIGHT} w-full cursor-pointer select-none items-center gap-1.5 rounded-md text-sm outline-hidden data-disabled:pointer-events-none data-disabled:cursor-not-allowed data-disabled:opacity-50 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0 *:[span]:last:flex *:[span]:last:items-center *:[span]:last:gap-2`,
          showDefaultIndicator ? "pr-8 pl-1.5" : "px-2"
        ),
        className
      )}
      data-slot="select-item"
      {...props}
    >
      {showCustomIndicator && (
        <SelectPrimitive.ItemIndicator
          keepMounted
          render={<span className="flex items-center justify-center" />}
        >
          {indicator}
        </SelectPrimitive.ItemIndicator>
      )}
      <SelectPrimitive.ItemText className="min-w-0 flex-1 truncate [&>svg]:me-2 [&>svg]:inline-block [&>svg]:align-[-0.2em]">
        {children}
      </SelectPrimitive.ItemText>
      {showDefaultIndicator && (
        <SelectPrimitive.ItemIndicator
          render={
            <span className="pointer-events-none absolute right-2 flex size-4 items-center justify-center" />
          }
        >
          <CheckIcon className="pointer-events-none" />
        </SelectPrimitive.ItemIndicator>
      )}
    </SelectPrimitive.Item>
  );
}

// =============================================================================
// SelectSeparator
// =============================================================================
export interface SelectSeparatorProps extends SelectPrimitive.Separator.Props {}

function SelectSeparator({ className, ...props }: SelectSeparatorProps) {
  return (
    <SelectPrimitive.Separator
      className={mergeClassName(
        "pointer-events-none -mx-1 my-1 h-px bg-border-muted",
        className
      )}
      data-slot="select-separator"
      {...props}
    />
  );
}

// =============================================================================
// SelectScrollUpButton
// =============================================================================
export interface SelectScrollUpButtonProps
  extends React.ComponentProps<typeof SelectPrimitive.ScrollUpArrow> {}

function SelectScrollUpButton({
  className,
  ...props
}: SelectScrollUpButtonProps) {
  return (
    <SelectPrimitive.ScrollUpArrow
      className={cn(
        "sticky top-0 z-10 flex h-6 w-full cursor-default items-center justify-center bg-popover [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      data-slot="select-scroll-up-button"
      {...props}
    >
      <ChevronUpIcon />
    </SelectPrimitive.ScrollUpArrow>
  );
}

// =============================================================================
// SelectScrollDownButton
// =============================================================================
export interface SelectScrollDownButtonProps
  extends React.ComponentProps<typeof SelectPrimitive.ScrollDownArrow> {}

function SelectScrollDownButton({
  className,
  ...props
}: SelectScrollDownButtonProps) {
  return (
    <SelectPrimitive.ScrollDownArrow
      className={cn(
        "sticky bottom-0 z-10 flex h-6 w-full cursor-default items-center justify-center bg-popover [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      data-slot="select-scroll-down-button"
      {...props}
    >
      <ChevronDownIcon />
    </SelectPrimitive.ScrollDownArrow>
  );
}

export type { SelectRootProps as SelectProps } from "@base-ui/react/select";
export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};
